-- Development seed data for Cardamom. Never run this against a real database.
--
-- Load it with ./db/seed.sh (see the README). It is safe to re-run: the seed
-- accounts below are deleted first, which cascades to their recipes and
-- favourites, and then everything is inserted again.
--
-- Every seed account uses the password Secret123!
--
--   maya@example.com   Free     25 recipes, 0 favourites   exactly at the Free limit
--   theo@example.com   Free     24 recipes, 1 favourite    at the limit via a favourite
--   priya@example.com  Premium  30 recipes, 2 favourites   more than the Free limit
--   sam@example.com    Free      3 recipes, 2 favourites   below the limit
--   nina@example.com   Free      0 recipes, 0 favourites   empty collection
--   bulk@example.com   Premium 500 recipes, 0 favourites   at the Premium limit (generated copies)
--
-- The hash below is Argon2id with libsodium's interactive limits, the same call
-- the backend uses in backend/Password.h.

SET @hash = '$argon2id$v=19$m=65536,t=2,p=1$UVGfPmMEWCPsyT0dLV6GCQ$8cA6eyjORn+eLbsPdGuSCdCLAgxQrUtatFBJwlpVWDo';
SET @free = (SELECT id FROM user_tiers WHERE tier_name = 'Free');
SET @premium = (SELECT id FROM user_tiers WHERE tier_name = 'Premium');

DELETE FROM users
WHERE email IN (
    'maya@example.com',
    'theo@example.com',
    'priya@example.com',
    'sam@example.com',
    'nina@example.com',
    'bulk@example.com'
);

INSERT INTO users (email, email_verified, display_name, password_hash, tier_id)
VALUES
    ('maya@example.com', TRUE, 'Maya Okafor', @hash, @free),
    ('theo@example.com', TRUE, 'Theo Lindqvist', @hash, @free),
    ('priya@example.com', TRUE, 'Priya Raman', @hash, @premium),
    ('sam@example.com', FALSE, 'Sam Delgado', @hash, @free),
    ('nina@example.com', TRUE, 'Nina Castellanos', @hash, @free),
    ('bulk@example.com', TRUE, 'Bulk Tester', @hash, @premium);

SET @maya = (SELECT id FROM users WHERE email = 'maya@example.com');
SET @theo = (SELECT id FROM users WHERE email = 'theo@example.com');
SET @priya = (SELECT id FROM users WHERE email = 'priya@example.com');
SET @sam = (SELECT id FROM users WHERE email = 'sam@example.com');
SET @bulk = (SELECT id FROM users WHERE email = 'bulk@example.com');

-- Maya: 25 everyday recipes, exactly the Free limit.
INSERT INTO recipes (user_id, name, visibility, servings, prep_minutes, cook_minutes, ingredient_list, steps, notes)
VALUES
    (@maya, 'Jollof Rice', 'public', 6, 20, 45,
     '2 cups long-grain rice\n400 g canned tomatoes\n1 red bell pepper\n1 onion\n2 tbsp tomato paste\n3 tbsp vegetable oil\n2 cups chicken stock\n1 tsp curry powder\n1 tsp dried thyme\n1 scotch bonnet (optional)\nSalt to taste',
     '1. Blend the tomatoes, bell pepper, half the onion and the scotch bonnet until smooth.\n2. Fry the remaining sliced onion in oil until soft, then stir in the tomato paste for 2 minutes.\n3. Add the blended mix, curry powder and thyme. Simmer 15 minutes until thick.\n4. Rinse the rice, add it with the stock and salt, cover tightly and cook on low 25 minutes.\n5. Rest 10 minutes off the heat, then fluff with a fork.',
     'A little smokiness from the bottom of the pot is the goal, not a mistake.'),
    (@maya, 'Chicken Yassa', 'private', 4, 30, 40,
     '8 chicken thighs\n4 onions, thinly sliced\n4 lemons, juiced\n4 tbsp Dijon mustard\n4 cloves garlic\n3 tbsp vegetable oil\n2 bay leaves\n1 tsp black pepper\nSalt',
     '1. Marinate the chicken in lemon juice, mustard, garlic, pepper and salt for at least 30 minutes.\n2. Brown the chicken in oil and set aside.\n3. Cook the onions in the same pan until very soft and golden, about 15 minutes.\n4. Return the chicken with the marinade and bay leaves, cover and simmer 25 minutes.\n5. Serve with rice.',
     NULL),
    (@maya, 'Peanut Stew', 'private', 6, 15, 40,
     '1 onion, chopped\n3 cloves garlic\n1 tbsp grated ginger\n2 sweet potatoes, cubed\n400 g canned tomatoes\n1/2 cup natural peanut butter\n4 cups vegetable stock\n200 g spinach\n1 tsp ground cumin\n1/2 tsp chili flakes\nSalt',
     '1. Soften the onion, garlic and ginger in a little oil.\n2. Add cumin, chili, sweet potato, tomatoes and stock. Simmer 20 minutes.\n3. Whisk the peanut butter with a ladle of hot broth, then stir it in.\n4. Add the spinach and cook until wilted. Season with salt.',
     'Freezes well. Add shredded chicken if you want it heartier.'),
    (@maya, 'Garlic Butter Shrimp', 'private', 2, 10, 8,
     '400 g raw shrimp, peeled\n4 tbsp butter\n4 cloves garlic, minced\n1 lemon\n2 tbsp chopped parsley\n1/4 tsp chili flakes\nSalt and pepper',
     '1. Pat the shrimp dry and season with salt and pepper.\n2. Melt the butter over medium-high heat and cook the garlic 30 seconds.\n3. Add the shrimp in one layer and cook 2 minutes per side.\n4. Finish with lemon juice, parsley and chili flakes.',
     'Great over pasta or with crusty bread.'),
    (@maya, 'Weeknight Chicken Fried Rice', 'private', 4, 10, 15,
     '3 cups cold cooked rice\n2 chicken breasts, diced\n2 eggs\n1 cup frozen peas and carrots\n3 spring onions\n3 tbsp soy sauce\n1 tbsp sesame oil\n2 tbsp vegetable oil\nSalt and white pepper',
     '1. Stir-fry the chicken in vegetable oil until cooked, then set aside.\n2. Scramble the eggs in the same pan and break them up.\n3. Add the rice and vegetables and fry on high heat 4 minutes.\n4. Return the chicken, add soy sauce, sesame oil and spring onions. Toss and season.',
     'Day-old rice fries better than fresh.'),
    (@maya, 'Black Bean Tacos', 'public', 4, 10, 10,
     '2 cans black beans, drained\n1 tsp ground cumin\n1 tsp smoked paprika\n1 lime\n8 corn tortillas\n1 avocado\n1/2 red onion, finely diced\nFresh coriander\nCrumbled feta\nSalt',
     '1. Warm the beans with cumin, paprika, salt and a splash of water. Mash about half.\n2. Toast the tortillas in a dry pan.\n3. Fill with beans, sliced avocado, red onion, coriander and feta. Squeeze lime over the top.',
     NULL),
    (@maya, 'Shakshuka', 'private', 3, 10, 25,
     '2 tbsp olive oil\n1 onion, diced\n1 red bell pepper, diced\n3 cloves garlic\n1 tsp ground cumin\n1 tsp sweet paprika\n800 g canned tomatoes\n6 eggs\nFeta and parsley to serve\nSalt and pepper',
     '1. Soften the onion and pepper in olive oil, then add garlic and spices.\n2. Add the tomatoes and simmer 15 minutes until thick. Season.\n3. Make six wells and crack an egg into each. Cover and cook 6 to 8 minutes until the whites set.\n4. Top with feta and parsley and serve with bread.',
     NULL),
    (@maya, 'Lemon Herb Roast Chicken', 'public', 4, 15, 80,
     '1 whole chicken, about 1.8 kg\n2 lemons\n1 head garlic\n4 tbsp softened butter\n2 tbsp chopped thyme and rosemary\n1 tsp salt\n1/2 tsp black pepper',
     '1. Heat the oven to 200C. Mix butter, herbs, zest of one lemon, salt and pepper.\n2. Rub the butter under and over the skin. Put the halved lemons and garlic in the cavity.\n3. Roast 75 to 80 minutes until the juices run clear.\n4. Rest 15 minutes before carving.',
     'Save the carcass for stock.'),
    (@maya, 'Tomato Basil Soup', 'private', 4, 10, 35,
     '2 tbsp olive oil\n1 onion, chopped\n2 carrots, chopped\n3 cloves garlic\n800 g canned tomatoes\n3 cups vegetable stock\n1 tsp sugar\nLarge handful of basil\n1/2 cup cream (optional)\nSalt and pepper',
     '1. Soften the onion, carrot and garlic in oil for 8 minutes.\n2. Add tomatoes, stock and sugar. Simmer 25 minutes.\n3. Blend until smooth with the basil. Stir in cream if using and season.',
     NULL),
    (@maya, 'Spinach and Feta Omelette', 'private', 1, 5, 5,
     '3 eggs\n1 handful baby spinach\n30 g feta\n1 tsp butter\nSalt and pepper',
     '1. Beat the eggs with salt and pepper.\n2. Wilt the spinach in butter, then pour over the eggs.\n3. Cook gently, scatter feta over one half and fold.',
     NULL),
    (@maya, 'Beef Chili', 'public', 8, 15, 90,
     '2 tbsp oil\n1 kg beef mince\n2 onions, diced\n4 cloves garlic\n2 tbsp chili powder\n1 tbsp ground cumin\n1 tsp oregano\n800 g canned tomatoes\n2 cans kidney beans\n1 cup beef stock\nSalt',
     '1. Brown the beef in batches and set aside.\n2. Soften the onions and garlic, then toast the spices 1 minute.\n3. Return the beef, add tomatoes, beans and stock. Simmer uncovered 75 minutes, stirring now and then.\n4. Season and serve with rice, cheese and sour cream.',
     'Better the next day.'),
    (@maya, 'Honey Garlic Salmon', 'private', 2, 5, 12,
     '2 salmon fillets\n2 tbsp honey\n2 tbsp soy sauce\n2 cloves garlic, minced\n1 tbsp rice vinegar\n1 tbsp oil\nSesame seeds',
     '1. Mix honey, soy, garlic and vinegar.\n2. Sear the salmon skin side down in oil 4 minutes, flip and cook 2 more.\n3. Pour in the sauce and spoon it over the fish until it thickens, about 2 minutes.\n4. Sprinkle with sesame seeds.',
     NULL),
    (@maya, 'Caprese Pasta Salad', 'private', 6, 15, 12,
     '400 g fusilli\n300 g cherry tomatoes, halved\n250 g mini mozzarella balls\nLarge bunch of basil\n4 tbsp olive oil\n2 tbsp balsamic vinegar\n1 clove garlic, grated\nSalt and pepper',
     '1. Cook the pasta in salted water, drain and cool under running water.\n2. Whisk oil, vinegar, garlic, salt and pepper.\n3. Toss everything together with torn basil.',
     'Make it a few hours ahead so the flavours mingle.'),
    (@maya, 'Banana Bread', 'public', 10, 15, 60,
     '3 very ripe bananas\n115 g melted butter\n150 g sugar\n1 egg\n1 tsp vanilla\n1 tsp baking soda\n1/4 tsp salt\n190 g plain flour',
     '1. Heat the oven to 175C and butter a loaf tin.\n2. Mash the bananas, then stir in butter, sugar, egg and vanilla.\n3. Mix in baking soda, salt and flour until just combined.\n4. Bake 55 to 60 minutes until a skewer comes out clean.',
     'Add a handful of walnuts or chocolate chips.'),
    (@maya, 'Oatmeal Raisin Cookies', 'private', 24, 15, 12,
     '225 g softened butter\n200 g brown sugar\n2 eggs\n1 tsp vanilla\n190 g plain flour\n1 tsp baking soda\n1 tsp cinnamon\n1/2 tsp salt\n270 g rolled oats\n150 g raisins',
     '1. Cream the butter and sugar, then beat in eggs and vanilla.\n2. Stir in flour, baking soda, cinnamon and salt, then the oats and raisins.\n3. Scoop onto lined trays and bake at 175C for 10 to 12 minutes.',
     NULL),
    (@maya, 'Greek Salad', 'private', 4, 15, NULL,
     '4 tomatoes, cut into wedges\n1 cucumber, sliced\n1 green bell pepper, sliced\n1/2 red onion, thinly sliced\n100 g kalamata olives\n200 g feta in one block\n3 tbsp olive oil\n1 tbsp red wine vinegar\n1 tsp dried oregano\nSalt',
     '1. Arrange the vegetables and olives in a bowl.\n2. Lay the feta on top and sprinkle with oregano.\n3. Dress with oil, vinegar and salt just before serving.',
     NULL),
    (@maya, 'Overnight Oats', 'private', 1, 5, NULL,
     '50 g rolled oats\n120 ml milk\n2 tbsp yoghurt\n1 tsp chia seeds\n1 tsp honey\nPinch of salt\nBerries to serve',
     '1. Stir everything except the berries together in a jar.\n2. Refrigerate overnight.\n3. Top with berries in the morning.',
     'Keeps for three days in the fridge.'),
    (@maya, 'Plantain Chips', 'private', 4, 10, 15,
     '3 green plantains\nVegetable oil for frying\nSalt\n1/2 tsp chili powder',
     '1. Peel the plantains and slice very thinly.\n2. Fry in batches in hot oil until golden and crisp, about 3 minutes.\n3. Drain on paper and toss with salt and chili powder while hot.',
     NULL),
    (@maya, 'Puff Puff', 'public', 6, 70, 15,
     '250 g plain flour\n60 g sugar\n1 tsp instant yeast\n1/2 tsp salt\n1/2 tsp nutmeg\n250 ml warm water\nOil for frying',
     '1. Whisk the dry ingredients, then add the water to make a thick batter.\n2. Cover and leave 1 hour until bubbly and doubled.\n3. Drop spoonfuls into hot oil and fry until deep golden, turning often.\n4. Drain and dust with sugar.',
     NULL),
    (@maya, 'Chicken Noodle Soup', 'private', 6, 15, 40,
     '1 tbsp oil\n1 onion, diced\n3 carrots, sliced\n3 celery stalks, sliced\n2 cloves garlic\n8 cups chicken stock\n2 chicken breasts\n200 g egg noodles\n2 tbsp chopped parsley\nSalt and pepper',
     '1. Soften the onion, carrot, celery and garlic in oil.\n2. Add the stock and chicken and simmer 20 minutes. Lift out the chicken and shred it.\n3. Cook the noodles in the broth, return the chicken and add parsley. Season.',
     NULL),
    (@maya, 'Mushroom Risotto', 'private', 4, 10, 35,
     '300 g arborio rice\n400 g mixed mushrooms, sliced\n1 onion, finely diced\n2 cloves garlic\n150 ml white wine\n1.2 litres hot vegetable stock\n50 g butter\n60 g grated parmesan\n2 tbsp olive oil\nSalt and pepper',
     '1. Fry the mushrooms in oil until browned and set aside.\n2. Soften the onion and garlic in half the butter, add the rice and stir 2 minutes.\n3. Add the wine, then the stock a ladle at a time, stirring, for about 20 minutes.\n4. Stir in mushrooms, remaining butter and parmesan. Season and rest 2 minutes.',
     NULL),
    (@maya, 'Baked Mac and Cheese', 'public', 6, 15, 30,
     '400 g macaroni\n60 g butter\n60 g plain flour\n900 ml milk\n300 g sharp cheddar, grated\n1 tsp mustard powder\n50 g breadcrumbs\nSalt and pepper',
     '1. Cook the macaroni 2 minutes less than the packet says.\n2. Melt the butter, whisk in the flour, then gradually whisk in milk until thick.\n3. Stir in most of the cheese and the mustard. Season and combine with the pasta.\n4. Top with remaining cheese and breadcrumbs. Bake at 200C for 25 minutes.',
     NULL),
    (@maya, 'Guacamole', 'private', 4, 10, NULL,
     '3 ripe avocados\n1 lime\n1/2 small red onion, finely diced\n1 tomato, seeded and diced\n1 jalapeno, minced\n2 tbsp chopped coriander\n1/2 tsp salt',
     '1. Mash the avocados with lime juice and salt.\n2. Fold in the onion, tomato, jalapeno and coriander.',
     'Press cling film onto the surface to keep it from browning.'),
    (@maya, 'Egusi Soup', 'private', 6, 20, 45,
     '1 cup ground egusi (melon seeds)\n500 g beef, cubed\n200 g smoked fish\n1/2 cup palm oil\n1 onion\n2 tomatoes\n1 scotch bonnet\n200 g spinach or bitter leaf\n1 tbsp ground crayfish\n2 stock cubes\nSalt',
     '1. Simmer the beef with onion, stock cubes and salt until tender. Keep the broth.\n2. Blend the tomatoes and pepper. Fry in palm oil 10 minutes.\n3. Mix the egusi with a little water into a paste and add in lumps. Fry 10 minutes without stirring too much.\n4. Add the broth, beef, fish and crayfish. Simmer 15 minutes, then stir in the greens.',
     NULL),
    (@maya, 'Simple Pancakes', 'public', 4, 5, 15,
     '190 g plain flour\n2 tbsp sugar\n2 tsp baking powder\n1/2 tsp salt\n300 ml milk\n1 egg\n2 tbsp melted butter',
     '1. Whisk the dry ingredients together.\n2. Whisk in milk, egg and butter until just combined. Lumps are fine.\n3. Cook ladlefuls on a medium hot buttered pan until bubbles form, then flip.',
     'Do not overmix or they go tough.');

-- Theo: 24 Nordic recipes, one short of the Free limit. A favourite below fills the last slot.
INSERT INTO recipes (user_id, name, visibility, servings, prep_minutes, cook_minutes, ingredient_list, steps, notes)
VALUES
    (@theo, 'Cardamom Buns', 'public', 16, 150, 15,
     '500 g plain flour\n250 ml milk\n75 g butter\n75 g sugar\n7 g instant yeast\n2 tsp ground cardamom\n1/2 tsp salt\nFilling: 100 g soft butter, 80 g sugar, 2 tsp ground cardamom\n1 egg, beaten\nPearl sugar',
     '1. Warm the milk and melt the butter in it. Mix with flour, sugar, yeast, cardamom and salt into a soft dough. Knead 10 minutes.\n2. Rise covered 1 hour until doubled.\n3. Roll into a rectangle, spread the filling over it, fold in thirds and cut into strips. Twist each strip and tie into a knot.\n4. Prove 45 minutes, brush with egg, sprinkle pearl sugar and bake at 220C for 12 to 15 minutes.',
     'Freshly ground cardamom makes a huge difference.'),
    (@theo, 'Swedish Meatballs', 'public', 4, 20, 25,
     '500 g beef and pork mince\n1 small onion, grated\n50 g breadcrumbs\n100 ml milk\n1 egg\n1/2 tsp allspice\n1 tsp salt\nBlack pepper\nButter for frying\nSauce: 2 tbsp butter, 2 tbsp flour, 400 ml beef stock, 100 ml cream, 1 tsp soy sauce',
     '1. Soak the breadcrumbs in milk 5 minutes, then mix with mince, onion, egg and seasoning.\n2. Roll into walnut-sized balls and fry in butter until browned all over.\n3. For the sauce, melt butter, whisk in flour, then stock, cream and soy. Simmer until thick.\n4. Return the meatballs to the sauce and warm through. Serve with potatoes and lingonberry jam.',
     NULL),
    (@theo, 'Cinnamon Rolls', 'private', 12, 120, 20,
     '500 g plain flour\n250 ml milk\n75 g butter\n60 g sugar\n7 g instant yeast\n1/2 tsp salt\nFilling: 100 g soft butter, 100 g brown sugar, 2 tbsp cinnamon\n1 egg, beaten',
     '1. Make the dough as for cardamom buns and let it rise 1 hour.\n2. Roll into a rectangle, spread the filling and roll up tightly. Cut into 12 pieces.\n3. Prove in a tin 45 minutes, brush with egg and bake at 200C for 18 to 20 minutes.',
     NULL),
    (@theo, 'Gravlax', 'private', 8, 15, NULL,
     '1 kg salmon fillet, skin on\n4 tbsp sugar\n4 tbsp coarse salt\n1 tbsp crushed white pepper\nLarge bunch of dill',
     '1. Mix sugar, salt and pepper. Rub all over the flesh side of the salmon.\n2. Cover with dill, wrap tightly and weigh down in the fridge.\n3. Turn every 12 hours. Cure 48 hours, then scrape off the cure and slice thinly.',
     'Serve with mustard dill sauce and rye bread.'),
    (@theo, 'Rye Bread', 'private', 12, 30, 50,
     '300 g rye flour\n200 g strong white flour\n7 g instant yeast\n350 ml warm water\n2 tbsp dark syrup or molasses\n1 tsp salt\n1 tsp fennel seeds',
     '1. Mix everything into a sticky dough and knead 8 minutes.\n2. Rise covered 1 hour.\n3. Shape into a loaf, prove 45 minutes and bake at 200C for 45 to 50 minutes.',
     NULL),
    (@theo, 'Pea Soup with Ham', 'private', 6, 10, 90,
     '500 g dried yellow peas, soaked overnight\n1 onion, chopped\n400 g smoked ham hock or gammon\n1.5 litres water\n1 tsp dried marjoram\n1 tsp mustard\nSalt and pepper',
     '1. Drain the peas and put them in a pot with onion, ham and water.\n2. Simmer 1.5 hours, skimming, until the peas break down.\n3. Remove the ham, dice the meat and return it. Add marjoram and mustard. Season.',
     'Traditionally eaten on Thursdays with pancakes after.'),
    (@theo, 'Pickled Cucumbers', 'private', 6, 10, NULL,
     '1 cucumber, very thinly sliced\n100 ml white vinegar\n100 ml water\n60 g sugar\n1/2 tsp salt\n2 tbsp chopped dill\n1/2 tsp white pepper',
     '1. Stir the vinegar, water, sugar and salt until dissolved.\n2. Add the cucumber, dill and pepper. Leave at least 1 hour before serving.',
     NULL),
    (@theo, 'Potato Pancakes', 'private', 4, 15, 20,
     '6 large potatoes, peeled\n2 eggs\n100 ml milk\n3 tbsp plain flour\n1 tsp salt\nButter for frying',
     '1. Grate the potatoes coarsely and squeeze out the liquid.\n2. Mix with eggs, milk, flour and salt.\n3. Fry thin pancakes in plenty of butter until crisp on both sides.\n4. Serve with fried bacon and lingonberry jam.',
     NULL),
    (@theo, 'Salmon Chowder', 'public', 4, 15, 25,
     '400 g salmon, cubed\n2 tbsp butter\n1 leek, sliced\n2 carrots, diced\n3 potatoes, diced\n1 litre fish or vegetable stock\n200 ml cream\n2 tbsp chopped dill\n1 bay leaf\nSalt and white pepper',
     '1. Soften the leek and carrot in butter.\n2. Add potatoes, stock and bay leaf. Simmer 12 minutes until the potatoes are tender.\n3. Add the salmon and cream and poach gently 4 minutes.\n4. Stir in dill and season.',
     NULL),
    (@theo, 'Mushroom Toast', 'private', 2, 5, 10,
     '300 g chanterelles or mixed mushrooms\n2 tbsp butter\n1 shallot, finely diced\n100 ml cream\n2 thick slices sourdough\nChopped parsley\nSalt and pepper',
     '1. Fry the mushrooms in a dry pan until their liquid evaporates.\n2. Add butter and shallot and cook 2 minutes. Add cream and bubble until thick.\n3. Season and spoon over toasted bread with parsley.',
     NULL),
    (@theo, 'Lingonberry Jam', 'private', 10, 5, 15,
     '500 g lingonberries, fresh or frozen\n250 g sugar\n50 ml water',
     '1. Simmer the berries and water 10 minutes.\n2. Stir in the sugar until dissolved and simmer 5 more minutes.\n3. Pour into a clean jar. Keeps a month in the fridge.',
     'Cranberries work as a substitute.'),
    (@theo, 'Oven Pancake', 'private', 4, 10, 30,
     '3 eggs\n500 ml milk\n180 g plain flour\n1/2 tsp salt\n1 tbsp sugar\n30 g butter\n150 g diced bacon (optional)',
     '1. Whisk eggs, milk, flour, salt and sugar into a smooth batter. Rest 20 minutes.\n2. Melt the butter in a roasting tin in a 225C oven. Scatter the bacon and pour in the batter.\n3. Bake 25 to 30 minutes until puffed and golden.',
     NULL),
    (@theo, 'Semla Buns', 'private', 12, 140, 12,
     '1 batch cardamom bun dough without the filling\n200 g almond paste\n100 ml milk\n400 ml whipping cream\n1 tbsp sugar\nIcing sugar',
     '1. Shape the dough into 12 round buns, prove and bake at 220C for 10 to 12 minutes. Cool.\n2. Cut off the tops and scoop out some crumb. Mix the crumb with almond paste and milk and spoon back in.\n3. Whip the cream with sugar, pipe on top, replace the lids and dust with icing sugar.',
     'Traditionally eaten before Lent, but nobody checks.'),
    (@theo, 'Apple Cake', 'public', 8, 20, 45,
     '4 apples\n150 g softened butter\n150 g sugar\n3 eggs\n180 g plain flour\n2 tsp baking powder\n1 tsp cinnamon\n1 tsp vanilla\nPinch of salt',
     '1. Cream the butter and sugar, then beat in the eggs one at a time and the vanilla.\n2. Fold in flour, baking powder and salt. Spread in a lined 22 cm tin.\n3. Press sliced apples into the top and sprinkle with cinnamon and sugar.\n4. Bake at 175C for 40 to 45 minutes.',
     NULL),
    (@theo, 'Beetroot Salad', 'private', 4, 15, NULL,
     '4 cooked beetroots, diced\n1 apple, diced\n1 small pickled cucumber, diced\n150 ml sour cream\n1 tbsp horseradish\n1 tsp mustard\nChopped chives\nSalt and pepper',
     '1. Mix the sour cream, horseradish and mustard.\n2. Fold in the beetroot, apple and cucumber. Season and top with chives.',
     NULL),
    (@theo, 'Open-Faced Shrimp Sandwich', 'private', 2, 15, 7,
     '2 slices dark rye bread\nButter\n2 eggs\n200 g cooked small shrimp\n2 tbsp mayonnaise\nLettuce\nDill and lemon wedges',
     '1. Boil the eggs 7 minutes, cool and slice.\n2. Butter the bread, add lettuce and egg slices.\n3. Pile on the shrimp, add a spoon of mayonnaise, dill and a squeeze of lemon.',
     NULL),
    (@theo, 'Herring Potato Salad', 'private', 4, 15, 20,
     '500 g waxy potatoes\n200 g pickled herring, chopped\n1 red onion, finely sliced\n1 apple, diced\n150 ml sour cream\n1 tbsp capers\nDill\nSalt and pepper',
     '1. Boil the potatoes until tender, cool and dice.\n2. Mix with the herring, onion, apple, capers and sour cream.\n3. Season and finish with dill.',
     NULL),
    (@theo, 'Cabbage Rolls', 'private', 4, 40, 60,
     '1 head white cabbage\n400 g pork mince\n100 g cooked rice\n1 onion, grated\n1 egg\n1 tsp salt\n1/2 tsp allspice\n2 tbsp butter\n2 tbsp dark syrup\n300 ml stock',
     '1. Blanch the cabbage leaves 3 minutes until pliable.\n2. Mix mince, rice, onion, egg and seasoning. Roll a spoonful in each leaf.\n3. Brown the rolls in butter, drizzle with syrup, add stock and bake covered at 175C for 1 hour.',
     NULL),
    (@theo, 'Ginger Snaps', 'public', 60, 60, 8,
     '100 g butter\n150 g sugar\n50 ml dark syrup\n50 ml water\n1 tbsp ground ginger\n1 tbsp cinnamon\n1 tsp ground cloves\n1 tsp baking soda\n300 g plain flour',
     '1. Melt butter, sugar, syrup and water together. Cool slightly.\n2. Stir in spices, baking soda and flour. Chill the dough overnight.\n3. Roll very thin, cut shapes and bake at 200C for 6 to 8 minutes.',
     'The dough keeps a week in the fridge.'),
    (@theo, 'Creamy Dill Potatoes', 'private', 4, 10, 25,
     '800 g new potatoes\n200 ml cream\n2 tbsp butter\n1 tbsp flour\n1 tsp sugar\n1 tbsp white vinegar\nLarge bunch of dill\nSalt and pepper',
     '1. Boil the potatoes until just tender.\n2. Melt the butter, stir in flour, then cream. Simmer until thick.\n3. Add sugar, vinegar, chopped dill and seasoning. Coat the potatoes.',
     NULL),
    (@theo, 'Rice Porridge', 'private', 4, 5, 45,
     '150 g short-grain rice\n300 ml water\n800 ml whole milk\n1 cinnamon stick\n1 tbsp butter\n1/2 tsp salt\nSugar and cinnamon to serve',
     '1. Simmer the rice in water with butter 10 minutes until absorbed.\n2. Add milk, cinnamon stick and salt. Simmer on low 35 minutes, stirring often.\n3. Serve with sugar and ground cinnamon.',
     NULL),
    (@theo, 'Sourdough Crispbread', 'private', 8, 20, 15,
     '200 g sourdough discard\n150 g rye flour\n50 g plain flour\n2 tbsp olive oil\n1 tsp salt\n1 tbsp mixed seeds',
     '1. Mix everything into a firm dough. Rest 30 minutes.\n2. Roll as thinly as possible on baking paper and prick all over.\n3. Bake at 200C for 12 to 15 minutes until crisp. Snap into pieces.',
     NULL),
    (@theo, 'Nettle Soup', 'private', 4, 15, 20,
     '200 g young nettle tops\n1 onion, chopped\n2 tbsp butter\n2 tbsp plain flour\n1 litre vegetable stock\n100 ml cream\nSalt and pepper\nHalved boiled eggs to serve',
     '1. Blanch the nettles 1 minute, drain and chop.\n2. Soften the onion in butter, stir in flour, then whisk in stock.\n3. Add the nettles and cream, simmer 10 minutes and blend. Season and serve with eggs.',
     'Wear gloves when picking.'),
    (@theo, 'Hot Chocolate with Cardamom', 'public', 2, 2, 8,
     '500 ml whole milk\n80 g dark chocolate, chopped\n1 tbsp sugar\n4 cardamom pods, crushed\nPinch of salt',
     '1. Warm the milk with the cardamom pods and let it steep 5 minutes.\n2. Strain, return to the heat and whisk in chocolate, sugar and salt until smooth.',
     NULL);

-- Priya: 30 South Indian and vegetarian recipes, more than the Free limit.
INSERT INTO recipes (user_id, name, visibility, servings, prep_minutes, cook_minutes, ingredient_list, steps, notes)
VALUES
    (@priya, 'Masala Dosa', 'public', 6, 30, 30,
     'Batter: 2 cups idli rice, 1/2 cup urad dal, 1/4 tsp fenugreek seeds, salt\nFilling: 4 boiled potatoes, 1 onion, 2 green chilies, 1 tsp mustard seeds, 10 curry leaves, 1/2 tsp turmeric, 1 tbsp oil, salt\nOil or ghee for cooking',
     '1. Soak the rice, dal and fenugreek 6 hours, grind smooth with water and ferment overnight. Add salt.\n2. For the filling, pop mustard seeds in oil, add curry leaves, chilies and onion. Add turmeric, crumbled potatoes and salt.\n3. Spread a ladle of batter thinly on a hot pan. Drizzle oil around the edge and cook until crisp.\n4. Spoon filling across the middle and fold. Serve with sambar and coconut chutney.',
     'The batter should smell slightly sour when ready.'),
    (@priya, 'Sambar', 'public', 6, 15, 35,
     '1 cup toor dal\n1 tbsp tamarind paste\n2 cups mixed vegetables (drumstick, carrot, pumpkin)\n1 onion\n2 tomatoes\n2 tbsp sambar powder\n1/2 tsp turmeric\n1 tsp mustard seeds\n10 curry leaves\n2 dried red chilies\n1 tbsp oil\nSalt',
     '1. Pressure cook the dal with turmeric until soft and mash.\n2. Simmer the vegetables, onion and tomato in water with tamarind and sambar powder 15 minutes.\n3. Add the dal and salt and simmer 10 minutes.\n4. Temper mustard seeds, chilies and curry leaves in oil and pour over.',
     NULL),
    (@priya, 'Coconut Chutney', 'public', 4, 10, 2,
     '1 cup fresh grated coconut\n2 tbsp roasted chana dal\n2 green chilies\n1 small piece ginger\nSalt\nTempering: 1 tsp oil, 1/2 tsp mustard seeds, 1 dried red chili, curry leaves',
     '1. Grind coconut, chana dal, chilies, ginger and salt with a little water to a thick paste.\n2. Temper the mustard seeds, chili and curry leaves in oil and pour over.',
     NULL),
    (@priya, 'Idli', 'private', 4, 20, 12,
     '2 cups idli rice\n1/2 cup urad dal\n1/4 tsp fenugreek seeds\nSalt\nOil for the moulds',
     '1. Soak the rice and dal separately 6 hours. Grind the dal fluffy and the rice slightly coarse. Mix and ferment overnight.\n2. Stir in salt, pour into greased idli moulds and steam 10 to 12 minutes.',
     NULL),
    (@priya, 'Rasam', 'public', 4, 10, 20,
     '2 tomatoes, chopped\n1 tbsp tamarind paste\n2 tsp rasam powder\n1/2 tsp turmeric\n4 cloves garlic, crushed\n1 tsp mustard seeds\n1 tsp cumin seeds\n2 dried red chilies\nCurry leaves\n1 tbsp ghee\nCoriander\nSalt',
     '1. Simmer the tomatoes, tamarind, rasam powder, turmeric, garlic and salt in 3 cups water 15 minutes.\n2. Temper mustard, cumin, chilies and curry leaves in ghee and pour over.\n3. Finish with coriander. Do not boil after adding the tempering.',
     'Good for a cold.'),
    (@priya, 'Lemon Rice', 'private', 4, 10, 10,
     '3 cups cooked rice\n2 lemons, juiced\n1/2 tsp turmeric\n1 tsp mustard seeds\n1 tbsp chana dal\n2 tbsp peanuts\n2 green chilies\nCurry leaves\n2 tbsp oil\nSalt',
     '1. Heat the oil and fry mustard seeds, chana dal and peanuts until golden.\n2. Add chilies, curry leaves and turmeric.\n3. Toss in the rice, lemon juice and salt.',
     NULL),
    (@priya, 'Tamarind Rice', 'private', 4, 15, 15,
     '3 cups cooked rice\n3 tbsp tamarind paste\n3 tbsp sesame oil\n1 tsp mustard seeds\n2 tbsp peanuts\n1 tbsp chana dal\n3 dried red chilies\n1/2 tsp turmeric\n1/4 tsp asafoetida\nCurry leaves\n1 tsp jaggery\nSalt',
     '1. Fry mustard seeds, peanuts, dal and chilies in sesame oil.\n2. Add curry leaves, turmeric, asafoetida, tamarind, jaggery and salt. Simmer until thick.\n3. Mix into the rice.',
     'Keeps well, so it is a classic travel food.'),
    (@priya, 'Curd Rice', 'private', 4, 10, NULL,
     '3 cups cooked rice, cooled\n1.5 cups plain yoghurt\n1/2 cup milk\n1 tsp mustard seeds\n1 green chili\n1 tbsp grated ginger\nCurry leaves\n1 tsp oil\nPomegranate seeds\nSalt',
     '1. Mash the rice slightly with yoghurt, milk and salt.\n2. Temper mustard seeds, chili, ginger and curry leaves in oil and stir in.\n3. Top with pomegranate.',
     NULL),
    (@priya, 'Upma', 'private', 4, 5, 15,
     '1 cup semolina\n1 onion, chopped\n2 green chilies\n1 tsp mustard seeds\n1 tbsp chana dal\n1 tbsp grated ginger\nCurry leaves\n2 tbsp oil\n2.5 cups hot water\n1 tbsp ghee\nSalt',
     '1. Dry roast the semolina until fragrant and set aside.\n2. Fry mustard, dal, chilies, ginger, curry leaves and onion in oil.\n3. Add the water and salt, bring to a boil, and pour in the semolina stirring constantly.\n4. Cover 3 minutes, then stir in ghee.',
     NULL),
    (@priya, 'Pongal', 'private', 4, 5, 25,
     '1 cup rice\n1/2 cup moong dal\n4 cups water\n3 tbsp ghee\n1 tsp cumin seeds\n1 tsp black pepper\n1 tbsp grated ginger\n10 cashews\nCurry leaves\nPinch of asafoetida\nSalt',
     '1. Roast the dal lightly, then pressure cook with rice and water until mushy.\n2. Fry cumin, pepper, ginger, cashews, curry leaves and asafoetida in ghee.\n3. Stir into the rice with salt.',
     NULL),
    (@priya, 'Medu Vada', 'private', 4, 30, 15,
     '1 cup urad dal, soaked 4 hours\n1 onion, finely chopped\n2 green chilies\n1 tbsp grated ginger\n1 tsp black peppercorns\nCurry leaves\nSalt\nOil for frying',
     '1. Grind the dal with very little water to a thick fluffy batter.\n2. Mix in onion, chilies, ginger, pepper, curry leaves and salt.\n3. Shape wet hands into rings and deep fry until golden.',
     NULL),
    (@priya, 'Vegetable Biryani', 'public', 6, 30, 45,
     '2 cups basmati rice\n3 cups mixed vegetables\n2 onions, sliced\n1 cup yoghurt\n2 tbsp ginger garlic paste\n2 tomatoes\n1 tbsp biryani masala\n1/2 tsp turmeric\n4 cloves\n2 bay leaves\n1 cinnamon stick\nSaffron in 2 tbsp milk\nMint and coriander\n3 tbsp ghee\nSalt',
     '1. Parboil the rice with whole spices and salt. Drain.\n2. Fry the onions until golden and set half aside. Add ginger garlic paste, tomatoes, masala, turmeric and vegetables. Cook 10 minutes, then stir in yoghurt.\n3. Layer rice and vegetables in a heavy pot with herbs, reserved onions and saffron milk.\n4. Cover tightly and cook on the lowest heat 25 minutes.',
     NULL),
    (@priya, 'Chana Masala', 'public', 4, 10, 30,
     '2 cans chickpeas\n2 onions, finely chopped\n3 tomatoes, pureed\n1 tbsp ginger garlic paste\n2 tsp coriander powder\n1 tsp cumin seeds\n1 tsp garam masala\n1/2 tsp turmeric\n1 tsp chili powder\n1 tsp amchur (dried mango powder)\n2 tbsp oil\nCoriander\nSalt',
     '1. Fry cumin seeds in oil, add onions and cook until deep golden.\n2. Add ginger garlic paste and ground spices, then tomatoes. Cook until the oil separates.\n3. Add chickpeas with 1 cup water and salt. Simmer 15 minutes, mashing a few.\n4. Finish with amchur, garam masala and coriander.',
     NULL),
    (@priya, 'Palak Paneer', 'public', 4, 15, 25,
     '500 g spinach\n250 g paneer, cubed\n1 onion, chopped\n2 tomatoes, chopped\n1 tbsp ginger garlic paste\n2 green chilies\n1 tsp cumin seeds\n1 tsp garam masala\n1/2 tsp turmeric\n2 tbsp cream\n2 tbsp oil or ghee\nSalt',
     '1. Blanch the spinach 2 minutes, cool in cold water and blend smooth.\n2. Fry cumin, onion, ginger garlic paste and chilies. Add tomatoes and spices and cook 5 minutes.\n3. Add the spinach puree and salt, simmer 5 minutes, then add paneer and cream.',
     NULL),
    (@priya, 'Aloo Gobi', 'private', 4, 15, 25,
     '1 cauliflower, in florets\n3 potatoes, cubed\n1 onion, chopped\n2 tomatoes, chopped\n1 tbsp grated ginger\n1 tsp cumin seeds\n1 tsp coriander powder\n1/2 tsp turmeric\n1/2 tsp chili powder\n1/2 tsp garam masala\n3 tbsp oil\nCoriander\nSalt',
     '1. Fry the potatoes in oil until golden and set aside.\n2. Fry cumin, onion and ginger, then add tomatoes and ground spices.\n3. Add cauliflower, potatoes and salt. Cover and cook on low 15 minutes.\n4. Finish with garam masala and coriander.',
     NULL),
    (@priya, 'Dal Tadka', 'public', 4, 5, 30,
     '1 cup toor dal\n1/2 tsp turmeric\n1 tomato, chopped\n2 tbsp ghee\n1 tsp cumin seeds\n4 cloves garlic, sliced\n2 dried red chilies\n1 onion, chopped\n1/2 tsp chili powder\nPinch of asafoetida\nCoriander\nSalt',
     '1. Pressure cook the dal with turmeric, tomato and salt until soft. Whisk smooth.\n2. Heat ghee, fry cumin, garlic, chilies and onion until golden. Add asafoetida and chili powder.\n3. Pour over the dal and top with coriander.',
     NULL),
    (@priya, 'Vegetable Korma', 'private', 4, 15, 30,
     '3 cups mixed vegetables\n1 onion\n1 tbsp ginger garlic paste\n1/2 cup cashews, soaked\n1/2 cup coconut milk\n1/2 cup yoghurt\n1 tsp coriander powder\n1/2 tsp garam masala\n1/4 tsp turmeric\n3 cardamom pods\n2 tbsp oil\nSalt',
     '1. Blend the cashews into a smooth paste.\n2. Fry cardamom and onion, add ginger garlic paste and ground spices.\n3. Add vegetables, cashew paste, coconut milk and 1/2 cup water. Simmer 15 minutes.\n4. Stir in yoghurt off the heat and season.',
     NULL),
    (@priya, 'Tomato Chutney', 'private', 6, 5, 20,
     '4 tomatoes, chopped\n1 onion, chopped\n4 dried red chilies\n1 tbsp urad dal\n1 tbsp tamarind paste\n2 tbsp oil\n1 tsp mustard seeds\nCurry leaves\nSalt',
     '1. Fry the dal and chilies in half the oil until golden, then add onion and tomatoes. Cook until soft.\n2. Cool and blend with tamarind and salt.\n3. Temper mustard seeds and curry leaves in the remaining oil and stir in.',
     NULL),
    (@priya, 'Mango Lassi', 'public', 2, 5, NULL,
     '1 cup ripe mango pulp\n1 cup plain yoghurt\n1/2 cup milk\n2 tbsp sugar\n1/4 tsp ground cardamom\nIce',
     '1. Blend everything until smooth and frothy.\n2. Serve over ice.',
     NULL),
    (@priya, 'Masala Chai', 'public', 2, 2, 10,
     '2 cups water\n1 cup whole milk\n2 tsp black tea leaves\n4 green cardamom pods, crushed\n1 small piece ginger, crushed\n1 cinnamon stick\n2 cloves\n2 tsp sugar',
     '1. Boil the water with the spices 5 minutes.\n2. Add tea and milk, bring back to a boil and simmer 3 minutes.\n3. Strain and sweeten.',
     NULL),
    (@priya, 'Paneer Tikka', 'private', 4, 70, 15,
     '400 g paneer, cubed\n1 cup thick yoghurt\n1 tbsp ginger garlic paste\n1 tsp chili powder\n1 tsp garam masala\n1/2 tsp turmeric\n1 tbsp lemon juice\n1 bell pepper and 1 onion, in chunks\n2 tbsp oil\nSalt',
     '1. Mix yoghurt with the spices, lemon juice, oil and salt. Coat the paneer and vegetables and marinate 1 hour.\n2. Thread onto skewers and grill or bake at 220C for 15 minutes, turning once.',
     NULL),
    (@priya, 'Bhindi Masala', 'private', 4, 10, 25,
     '500 g okra, trimmed and cut\n1 onion, sliced\n2 tomatoes, chopped\n1 tsp cumin seeds\n1 tsp coriander powder\n1/2 tsp turmeric\n1/2 tsp chili powder\n1 tsp amchur\n3 tbsp oil\nSalt',
     '1. Fry the okra in 2 tbsp oil until no longer slimy, about 10 minutes. Set aside.\n2. Fry cumin and onion, then tomatoes and ground spices.\n3. Return the okra, add amchur and salt and cook 5 minutes.',
     'Make sure the okra is completely dry before cutting.'),
    (@priya, 'Rajma', 'private', 4, 10, 40,
     '2 cans red kidney beans\n2 onions, finely chopped\n3 tomatoes, pureed\n1 tbsp ginger garlic paste\n1 tsp cumin seeds\n2 tsp coriander powder\n1 tsp garam masala\n1/2 tsp turmeric\n1 tsp chili powder\n2 tbsp oil\nSalt',
     '1. Fry cumin seeds, then onions until golden. Add ginger garlic paste.\n2. Add tomatoes and ground spices and cook until the oil separates.\n3. Add the beans with 1.5 cups water and salt. Simmer 25 minutes, mashing some beans to thicken.',
     NULL),
    (@priya, 'Pav Bhaji', 'private', 4, 15, 30,
     '3 potatoes, boiled\n1 cup cauliflower, chopped\n1/2 cup peas\n1 bell pepper, chopped\n2 onions, chopped\n3 tomatoes, chopped\n2 tbsp pav bhaji masala\n1 tsp chili powder\n1/2 tsp turmeric\n3 tbsp butter\n8 soft bread rolls\nLemon and coriander\nSalt',
     '1. Boil the cauliflower and peas until soft.\n2. Fry onions in butter, add bell pepper, tomatoes and spices. Cook until mushy.\n3. Add all vegetables and mash together with a little water. Simmer 10 minutes.\n4. Toast the rolls in butter and serve with lemon and coriander.',
     NULL),
    (@priya, 'Vegetable Pulao', 'private', 4, 10, 25,
     '1.5 cups basmati rice\n2 cups mixed vegetables\n1 onion, sliced\n1 tsp cumin seeds\n1 bay leaf\n3 cloves\n1 cinnamon stick\n2 green chilies\n2 tbsp ghee\n3 cups water\nSalt',
     '1. Fry the whole spices and onion in ghee until golden.\n2. Add vegetables, chilies, rinsed rice and salt. Stir 2 minutes.\n3. Add water, cover and cook on low 18 minutes. Rest 5 minutes.',
     NULL),
    (@priya, 'Kheer', 'public', 6, 5, 45,
     '1/2 cup basmati rice\n1 litre whole milk\n1/2 cup sugar\n1/2 tsp ground cardamom\n2 tbsp chopped pistachios and almonds\nPinch of saffron',
     '1. Simmer the rinsed rice in milk on low, stirring often, 35 minutes until thick.\n2. Add sugar, cardamom and saffron and cook 5 more minutes.\n3. Serve warm or chilled with nuts.',
     NULL),
    (@priya, 'Mysore Pak', 'private', 12, 5, 20,
     '1 cup chickpea flour (besan)\n1.5 cups sugar\n1/2 cup water\n1 cup ghee',
     '1. Boil the sugar and water to a one-string syrup.\n2. Sift in the besan while whisking. Add ghee a ladle at a time, stirring constantly.\n3. When the mixture froths and leaves the sides, pour into a greased tin. Cut while warm.',
     'Work fast once it starts to froth.'),
    (@priya, 'Avial', 'private', 6, 20, 25,
     '4 cups mixed vegetables cut into batons (drumstick, carrot, beans, pumpkin, raw banana)\n1 cup grated coconut\n3 green chilies\n1 tsp cumin seeds\n1/2 tsp turmeric\n1/2 cup yoghurt\n2 tbsp coconut oil\nCurry leaves\nSalt',
     '1. Simmer the vegetables with turmeric and salt in a little water until just tender.\n2. Grind the coconut, chilies and cumin coarsely and stir in. Cook 5 minutes.\n3. Stir in yoghurt, coconut oil and curry leaves off the heat.',
     NULL),
    (@priya, 'Beetroot Poriyal', 'private', 4, 10, 15,
     '3 beetroots, finely diced\n1/2 cup grated coconut\n1 tsp mustard seeds\n1 tbsp urad dal\n2 dried red chilies\nCurry leaves\n1 tbsp oil\nSalt',
     '1. Fry mustard, dal, chilies and curry leaves in oil.\n2. Add beetroot and salt, cover and cook 12 minutes with a splash of water.\n3. Stir in the coconut.',
     NULL),
    (@priya, 'Carrot Halwa', 'public', 6, 15, 45,
     '1 kg carrots, grated\n1 litre whole milk\n3/4 cup sugar\n4 tbsp ghee\n1/2 tsp ground cardamom\n2 tbsp raisins\n2 tbsp chopped cashews',
     '1. Simmer the carrots in milk, stirring, until the milk is absorbed, about 35 minutes.\n2. Add sugar and cook until thick again.\n3. Fry the nuts and raisins in ghee, add to the halwa with cardamom and cook 5 minutes.',
     NULL);

-- Sam: a small collection well below the limit.
INSERT INTO recipes (user_id, name, visibility, servings, prep_minutes, cook_minutes, ingredient_list, steps, notes)
VALUES
    (@sam, 'Grilled Cheese Sandwich', 'public', 1, 2, 6,
     '2 slices bread\n2 slices cheddar\n1 tbsp butter\nPinch of salt',
     '1. Butter the outside of both slices.\n2. Put the cheese between them and cook in a pan on medium heat 3 minutes per side.',
     'Low heat and patience beats high heat every time.'),
    (@sam, 'Scrambled Eggs', 'private', 1, 2, 4,
     '3 eggs\n1 tbsp butter\nSalt and pepper\nChives',
     '1. Whisk the eggs with salt.\n2. Melt butter on low heat, add eggs and stir slowly until just set.\n3. Top with pepper and chives.',
     NULL),
    (@sam, 'Microwave Baked Potato', 'private', 1, 2, 8,
     '1 large potato\nButter\nSalt\nGrated cheese',
     '1. Prick the potato all over and microwave 4 minutes per side.\n2. Split, add butter, salt and cheese.',
     NULL);

-- Favourites. Only public recipes are favourited across accounts.
INSERT INTO recipe_favorites (user_id, recipe_id)
VALUES
    (@theo, (SELECT id FROM recipes WHERE user_id = @priya AND name = 'Masala Dosa')),
    (@priya, (SELECT id FROM recipes WHERE user_id = @theo AND name = 'Cardamom Buns')),
    (@priya, (SELECT id FROM recipes WHERE user_id = @maya AND name = 'Jollof Rice')),
    (@sam, (SELECT id FROM recipes WHERE user_id = @priya AND name = 'Chana Masala')),
    (@sam, (SELECT id FROM recipes WHERE user_id = @maya AND name = 'Banana Bread'));

-- Bulk: 500 generated copies of Priya's recipes, for search timing at the Premium limit.
INSERT INTO recipes (user_id, name, visibility, servings, prep_minutes, cook_minutes, ingredient_list, steps, notes)
WITH RECURSIVE batch AS (
    SELECT 1 AS n
    UNION ALL
    SELECT n + 1 FROM batch WHERE n < 17
)
SELECT
    @bulk,
    CONCAT(r.name, ' (copy ', b.n, ')'),
    r.visibility,
    r.servings,
    r.prep_minutes,
    r.cook_minutes,
    r.ingredient_list,
    r.steps,
    r.notes
FROM batch b
CROSS JOIN recipes r
WHERE r.user_id = @priya
ORDER BY b.n, r.id
LIMIT 500;

-- Spread creation dates over the last four months so the collection has a realistic order.
UPDATE recipes
SET created_at = NOW() - INTERVAL (id % 120) DAY - INTERVAL (id % 23) HOUR,
    updated_at = created_at
WHERE user_id IN (@maya, @theo, @priya, @sam, @bulk);
